('string_quest_completed',        'Quest completed %quest',                                             0, 0, '', 'Quête complétée %quest',                   'Quest abgeschlossen %quest',                    '任务完成 %quest',       '', 'Misión completada %quest',                '', 'Задание выполнено %quest'),
('string_quest_log_full',         'Quest log is full',                                                  0, 0, '', 'Journal de quête plein',                   'Questtagebuch ist voll',                        '任务日志已满',          '', 'Diario de misiones lleno',                '', 'Журнал заданий полон'),
('string_quest_failed_timer',     'Failed timer for quest, abandoning',                                 0, 0, '', 'Temps écoulé pour la quête, abandon',      'Zeit für Quest abgelaufen, aufgegeben',          '任务时间超时，放弃',     '', 'Tiempo agotado para misión, abandonando', '', 'Время задания вышло, бросаю'),
('string_clearing_travel',        'Clearing travel target',                                             0, 0, '', 'Effacement de la cible de voyage',         'Reiseziel wird gelöscht',                       '清除旅行目标',          '', 'Borrando objetivo de viaje',              '', 'Сбрасываю цель путешествия'),
('string_too_far_away_obj',       'It is too far away',                                                 0, 0, '', 'C\'est trop loin',                         'Es ist zu weit weg',                            '太远了',               '', 'Está demasiado lejos',                    '', 'Это слишком далеко'),
('string_glyphs_no_sockets',      'Not enough empty sockets for all glyphs.',                           0, 0, '', 'Pas assez d\'emplacements vides pour tous les glyphes.', 'Nicht genug freie Slots für alle Glyphen.', '没有足够的空插槽容纳所有雕文。', '', 'No hay suficientes ranuras vacías para todos los glifos.', '', 'Недостаточно пустых слотов для всех глифов.'),
('string_glyphs_updated',         'Glyphs updated.',                                                    0, 0, '', 'Glyphes mis à jour.',                      'Glyphen aktualisiert.',                         '雕文已更新。',          '', 'Glifos actualizados.',                    '', 'Глифы обновлены.'),
('string_got_quest',              'Got quest %quest',                                                   0, 0, '', 'Obtenu la quête %quest',                   'Quest erhalten %quest',                         '获得任务 %quest',       '', 'Misión obtenida %quest',                  '', 'Получено задание %quest'),
('string_welcome_back',           'Welcome back!',                                                      0, 0, '', 'Bon retour!',                              'Willkommen zurück!',                            '欢迎回来！',            '', '¡Bienvenido de vuelta!',                  '', 'С возвращением!'),
('string_join_next_relogin',      'I will join you at your next relogin',                               0, 0, '', 'Je te rejoindrai à ta prochaine reconnexion', 'Ich trete dir bei deiner nächsten Anmeldung bei.', '你下次登录时我将加入你。', '', 'Me uniré en tu próximo inicio de sesión.', '', 'Присоединюсь при следующем входе в игру'),
('string_max_characters',         'You already have the maximum number of characters',                  0, 0, '', 'Tu as déjà le nombre maximum de personnages',    'Du hast bereits die maximale Anzahl an Charakteren.', '你已经有最多数量的角色了', '', 'Ya tienes el máximo de personajes.', '', 'У тебя уже максимальное количество персонажей'),
('string_hire_too_high_level',    'You cannot hire higher level characters than you',                   0, 0, '', 'Tu ne peux pas recruter des personnages de niveau plus élevé que toi.', 'Du kannst keine Charaktere mit höherem Level anheuern als du.', '你不能招募等级比你高的角色。', '', 'No puedes contratar personajes de nivel más alto que tú.', '', 'Нельзя нанять персонажей выше твоего уровня'),
('string_stay_pos_too_far',       'The stay position is too far to return. I am going to stay where I am now', 0, 0, '', 'La position d\'arrêt est trop loin pour revenir. Je reste où je suis.', 'Die Warteposition ist zu weit. Ich bleibe wo ich bin.', '停留位置太远无法返回，我就待在原地了。', '', 'La posición de espera está demasiado lejos. Me quedo donde estoy.', '', 'Позиция ожидания слишком далеко. Остаюсь здесь.'),
('string_wait_for_me',            'Wait for me!',                                                       0, 0, '', 'Attendez-moi!',                            'Wartet auf mich!',                              '等等我！',              '', '¡Espérenme!',                             '', 'Подождите меня!'),
('string_ai_reset',               'AI was reset to defaults',                                           0, 0, '', 'L\'IA a été réinitialisée par défaut.',     'KI wurde auf Standard zurückgesetzt.',           'AI已重置为默认值。',    '', 'La IA ha sido restablecida.',              '', 'ИИ сброшен к настройкам по умолчанию');
